pub fun env_file_load(file: Text = ".env"): Null? {
    for line in lines(file)? {
        line = trim(line)
        if len(line) == 0 or starts_with(line, "#")  {
            continue
        }

        const eq_index = text_find(line, "=")
        if eq_index <= 0 {
            continue
        }

        const key = slice(line, 0, eq_index)
        let value = slice(line, eq_index + 1)

        if starts_with(value, "\"") or starts_with(value, "'") {
            value = slice(value, 1, len(value))
        }
        if ends_with(value, "\"") or ends_with(value, "'") {
            value = len(value) > 1 then slice(value, 0, len(value) - 1) else ""
        }

        env_var_set(key, value)?
    }
}

import * from "std/fs"
import { array_find } from "std/array"
import * from "std/text"

pub fun env_var_load(var: Text, file: Text = ".env"): Text? {
    for line in lines(file)? {
        line = trim(line)
        if len(line) == 0 or starts_with(line, "#")  {
            continue
        }

        const eq_index = text_find(line, "=")
        if eq_index <= 0 {
            continue
        }

        const key = slice(line, 0, eq_index)
        if key != var {
            continue
        }

        let value = slice(line, eq_index + 1)

        if starts_with(value, "\"") or starts_with(value, "'") {
            value = slice(value, 1, len(value))
        }
        if ends_with(value, "\"") or ends_with(value, "'") {
            value = len(value) > 1 then slice(value, 0, len(value) - 1) else ""
        }

        env_var_set(key, value)?
    }
    return env_var_get(var)?
}

