    let files = []
    for path in paths {
        const matches = trust $ __glob_path="{path}"; __glob_ifs="\$IFS"; IFS=\$'\\n'; for __glob_file in \$__glob_path; do if [ -e "\$__glob_file" ] || [ -L "\$__glob_file" ]; then printf '%s\n' "\$__glob_file"; fi; done; IFS="\$__glob_ifs" $
