pub fun file_compress(files: [Text], target: Text): Null? {
    // Reject paths starting with '-' to prevent option injection
    for file in files {
        if starts_with(file, "-") {
            echo("Error: File path cannot start with '-': {file}")
            fail(1)
        }
    }
    if {
        match_regex(target, "\.(tar\.bz2|tbz|tbz2)$", true): silent $ tar -cjf "{target}" "{files}" $?
        match_regex(target, "\.(tar\.gz|tgz)$", true): silent $ tar -czf "{target}" "{files}" $?
        match_regex(target, "\.(tar\.xz|txz)$", true): silent $ tar -cJf "{target}" "{files}" $?
        match_regex(target, "\.bz2$"): $ bzip2 -k -c "{files}" > "{target}" $?
        match_regex(target, "\.deb$"): $ dpkg-deb --build "{files}" "{target}" $?
        match_regex(target, "\.gz$"): $ gzip -k -c "{files}" > "{target}" $?
        match_regex(target, "\.rar$"): silent $ rar a -y "{target}" "{files}" $?
        match_regex(target, "\.rpm$"): $ rpmbuild -bb --buildroot "{files}" -D "_rpmdir=\$(dirname "{target}")" specfile.spec $?
        match_regex(target, "\.tar$", true): $ tar -cf "{target}" "{files}" $?
        match_regex(target, "\.xz$"): $ xz -k -c "{files}" > "{target}" $?
        match_regex(target, "\.7z$"): silent $ 7z a -y "{target}" "{files}" $?
        match_regex(target, "\.(zip|war|jar)$", true): silent $ zip -r "{target}" "{files}" $?
        else {
            echo("Error: Unsupported file type")
            fail(3)
        }
    }
}

import * from "std/env"
import * from "std/text"

/// Downloads a file from a given URL and saves it to a specified path using available command-line tools.
///
/// It checks for the availability of common command-line tools (`curl`, `wget`, and `aria2c`, in order) and uses the first available tool to perform the download.
/// If none of the tools are available, the function fails.
///
/// ### Usage
/// ```ab
/// file_download("https://example.com/file.zip", "/tmp/file.zip")
/// ```
pub fun file_download(url: Text, path: Text): Null? {
    if {
        is_command("curl") {
            silent trust $ curl -L -o "{path}" "{url}" $
        }
        is_command("wget") {
            silent trust $ wget "{url}" -P "{path}" $
        }
        is_command("aria2c") {
            silent trust $ aria2c "{url}" -d "{path}" $
        }
        else {
            fail 1
        }
    }
}

/// Makes a HTTP request using available command-line tools or bash's network sockets as failover.
///
/// For POST requests with a custom data type, you should include `content-type` header in `headers[]`.
/// 
/// ### Usage
/// ```ab
/// let response = trust fetch("https://example.com")
///
/// // POST request example
/// let post_request = trust fetch("https://example.com", "POST", "hello world!", [
///     "content-type: text/plain"
/// ])
/// ```
pub fun fetch(url: Text, method: Text = "GET", data: Text = "", headers: [Text] = [""]): Text? {
    if {
        is_command("curl") {
            let header_args = [Text]
            let post_data = [Text]
            if len(data) > 0:
                post_data += ["-d", data]

            for header in headers {
                if len(header) > 0:
                    header_args += ["-H", header]
            }

            const output = trust $ curl -L "{url}" --silent -S -X "{method}" "{header_args}" "{post_data}" 2>&1 $

            const curl_status = status()
            if curl_status > 0 {
                printf("\x1b[1;3;97;41m%s\x1b[0m\n", ["curl request failed with error: {output}"])
                exit(curl_status)
            }
            return output
        }
        is_command("wget") {
            let header_args = [Text]
            let post_data = [Text]
            if len(data) > 0:
                post_data += ["--body-data", data]
            for header in headers {
                if len(header) > 0:
                    header_args += ["--header", header]
            }
            return $ wget "{url}" -qO- --method="{method}" "{header_args}" "{post_data}" $ failed {
                printf("\x1b[1;3;97;41m%s\x1b[0m\n", ["wget request failed with exit code {status()}"])
                exit(status())
            }
        }
        else {
            if shellname() == "bash" and match_regex(url, "http://") {
                let full_headers = ""
                let port = 80
                let path = ""
                url = replace(url, "http://", "")
                let parts = split_lines(replace_one(url, "/", "\n")) // split host and path
                url = parts[0]

                if match_regex(url, ":([0-9][0-9]+)", true) { // https://github.com/amber-lang/amber/pull/906#discussion_r2616210649
                    path = parts[1]
                    parts = split_lines(replace_one(url, ":", "\n")); // split IP/domain and port
                    url = parts[0]
                    port = parse_int(parts[1])?
                } else {
                    path = len(parts[1]) > 0 then parts[1] else ""
                }

                let has_headers = false
                for header in headers {
                    if len(header) > 1 {
                        full_headers += "{header}\r\n"
                        has_headers = true
                    }
                }

                if len(data) > 0 {
                    full_headers += "content-length: {len(data)}\r\n" 
                    if not has_headers: full_headers += "content-type: application/x-www-form-urlencoded\r\n" 
                    full_headers += "\r\n{data}\r\n"
                }

              $ exec 3<>/dev/tcp/"{url}"/"{port}" $ succeeded {
                let http_code = 0
                url = port != 80 then "{url}:{port}" else url
                const vers = shellversion()
                trust $ printf "%s\r\n" "{method} /{path} HTTP/1.1\r\nhost: {url}\r\nconnection: close\r\nuser-agent: Amber/bash-{vers[0]}.{vers[1]}.{vers[2]}\r\naccept: */*\r\n{full_headers}" >&3 $
                trust $
                  read -r _ {nameof(http_code)} _ <&3
                  while IFS= read -r line; do 
                    [[ "\$line" == \$'\r' || -z "\$line" ]] && break 
                  done <&3 
                $
                if http_code > 226 { // all official HTTP 2** codes go up to 226
                    return "{http_code}" // as for now, the best way is to return HTTP code since exit codes can't be >255
                } else {
                    return trust $ cat <&3 && exec 3>&- $
                }
              }
              const socket_status = status()
              printf("\x1b[1;3;97;41m%s\x1b[0m\n", ["Request failed with exit code {socket_status}"])
              exit(socket_status)
            } else {
              printf("\x1b[1;3;97;41m%s\x1b[0m\n", ["No connection method is available, aborting"])
              exit(1)
            }
        }
    }
}

/// Sums an array's contents
///
/// ### Usage
/// ```ab
/// let total = math_sum([1, 2, 3, 4, 5])
/// echo(total) // 15
/// ```
#[allow_absurd_cast]
pub fun math_sum(list) {
    let sum = 0
    for item in list: sum += item
    return sum
}

/// Returns a number, rounded to the nearest integer
///
/// ### Usage
/// ```ab
/// let rounded = math_round(3.7)
/// echo(rounded) // 4
/// ```
#[allow_absurd_cast]
pub fun math_round(number: Num): Int {
    if number > 0 {
        return trust $ awk 'BEGIN \{ printf "%d", (ARGV[1]+0.5)/1 }' "{number}" $ as Int
    }

    return trust $ awk 'BEGIN \{ printf "%d", (ARGV[1]-0.5)/1 }' "{number}" $ as Int
}

/// Returns the largest integer less than or equal to a number
///
/// ### Usage
/// ```ab
/// let floored = math_floor(3.9)
/// echo(floored) // 3
/// ```
#[allow_absurd_cast]
pub fun math_floor(number: Num): Int {
    return trust $ awk '\{printf "%d", (\$1 < 0 ? int(\$1) - 1 : int(\$1))}' <<< "{number}" $ as Int
}

/// Returns the smallest integer greater than or equal to a number
///
/// ### Usage
/// ```ab
/// let ceiled = math_ceil(3.1)
/// echo(ceiled) // 4
/// ```
#[allow_absurd_cast]
pub fun math_ceil(number: Num): Int {
    return math_floor(number) + 1
}

/// Returns the absolute value of a number
///
/// ### Usage
/// ```ab
/// let absolute = math_abs(-42)
/// echo(absolute) // 42
/// ```
#[allow_absurd_cast]
pub fun math_abs(number) {
    if number < 0: return -number
    return number
}

/// Asserts that a boolean condition is true. Fails the test with exit code `1` if false.
/// ### Usage
/// ```ab
/// let user_age = 18
/// assert(user_age >= 18)
/// ```
pub fun assert(condition: Bool) {
    if not condition {
        echo("Assertion failed")
        fail 1
    }
}

/// Asserts that a boolean condition is false. Fails the test with exit code `1` if true.
/// ### Usage
/// ```ab
/// let user_age = 17
/// refute(user_age >= 18)
/// ```
pub fun refute(condition: Bool) {
    assert(not condition)?
}

/// Asserts that two values are equal. Fails the test with exit code `1` if they are not equal.
/// ### Usage
/// ```ab
/// let expected = [1, 2, 3]
/// let actual = [1, 2, 3]
/// assert_eq(expected, actual)
/// ```
pub fun assert_eq(left, right) {
    if left != right {
        echo("Assertion failed: {left} != {right}")
        fail 1
    }
}

pub fun replace(source, search, replace) {
    // Here we use a command to avoid #646
    let result = ""
    if shellname() == "ksh" or (shellname() == "bash" and shellversion() >= [4, 3]) {
        trust $ {nameof(result)}="\$\{{nameof(source)}//"\$\{{nameof(search)}}"/"\$\{{nameof(replace)}}"}" $
    } else {
        trust $ {nameof(result)}="\$\{{nameof(source)}//"\$\{{nameof(search)}}"/\$\{{nameof(replace)}}}" $
    }
    return result
}

pub fun replace_one(source, search, replace) {
    // Here we use a command to avoid #646
    let result = ""
    if shellname() == "ksh" or (shellname() == "bash" and shellversion() >= [4, 3]) {
        trust $ {nameof(result)}="\$\{{nameof(source)}/"\$\{{nameof(search)}}"/"\$\{{nameof(replace)}}"}" $
    } else {
        trust $ {nameof(result)}="\$\{{nameof(source)}/"\$\{{nameof(search)}}"/\$\{{nameof(replace)}}}" $
    }
    return result
}

fun sed_version(): Int {
    // We can't match against a word "GNU" because
    // alpine's busybox sed returns "This is not GNU sed version"
    trust $ re='Copyright.+Free Software Foundation'; [[ \$(command sed --version 2>/dev/null) =~ \$re ]] $
    if status() == 0 {
        return SED_VERSION_GNU
    }
    // On BSD single `sed` waits for stdin. We must use `sed --help` to avoid this.
    trust $ re='BusyBox'; [[ \$(command sed --help 2>&1) =~ \$re ]] $
    if status() == 0 {
        return SED_VERSION_BUSYBOX
    }
    return SED_VERSION_UNKNOWN
}

pub fun replace_regex(source: Text, search: Text, replace_text: Text, extended: Bool = false): Text {
    trust {
        const sed_version = sed_version()
        search = replace(search, "/", "\\/")
        replace_text = replace(replace_text, "/", "\\/")
        if sed_version == SED_VERSION_GNU or sed_version == SED_VERSION_BUSYBOX {
            // '\b' is supported but not in POSIX standards. Disable it
            search = replace(search, "\\b", "\\\b")
        }
        if extended {
            // GNU sed versions 4.0 through 4.2 support extended regex syntax,
            // but only via the "-r" option
            if sed_version == SED_VERSION_GNU {
                return $ command sed -r -e "s/{search}/{replace_text}/g" <<<"{source}" $
            } else {
                return $ command sed -E -e "s/{search}/{replace_text}/g" <<<"{source}" $
            }
        } else {
            if sed_version == SED_VERSION_GNU or sed_version == SED_VERSION_BUSYBOX {
                // GNU Sed BRE handle \| as a metacharacter, but it is not POSIX standands. Disable it
                search = replace(search, "\|", "|")
            }
            return $ command sed -e "s/{search}/{replace_text}/g" <<<"{source}" $
        }
    }
}

pub fun split(text: Text, delimiter: Text): [Text] {
    let result = [Text]
    // zsh uses -A for array, bash uses -a, ksh is VERY bad at splitting anything
    trust {
        if {
            shellname() == "zsh": $ IFS="{delimiter}" read -rd '' -A {nameof(result)} < <(printf %s "\${nameof(text)}") $
            shellname() == "ksh" {
                if delimiter == "\n":
                    $ while read -r -d \$'\\n'; do {nameof(result)}+=("\$REPLY"); done < <(echo "\${nameof(text)}") $
                else:
                    $ IFS="{delimiter}" read -rd '' -a {nameof(result)} < <(printf %s "\${nameof(text)}") $
            } 
            shellname() == "bash": $ IFS="{delimiter}" read -rd '' -a {nameof(result)} < <(printf %s "\${nameof(text)}") $
        }
    }
    return result
}

pub fun split_lines(text: Text): [Text] {
    return split(text, "\n")
}

pub fun split_words(text: Text): [Text] {
    return split(text, " ")
}

pub fun join(list: [Text], delimiter: Text): Text {
    return trust $ IFS="{delimiter}" ; printf "%s\n" "\$\{{nameof(list)}[*]}" $
}

pub fun trim_left(text: Text): Text {
    let result = ""
    trust $ {nameof(result)}="\$\{{nameof(text)}#"\$\{{nameof(text)}%%[![:space:]]*}"}" $
    return result
}

pub fun trim_right(text: Text): Text {
    let result = ""
    trust $ {nameof(result)}="\$\{{nameof(text)}%"\$\{{nameof(text)}##*[![:space:]]}"}" $
    return result
}

pub fun trim(text: Text): Text {
    let result = ""
    trust $ {nameof(result)}="\$\{{nameof(text)}#"\$\{{nameof(text)}%%[![:space:]]*}"}" $
    trust $ {nameof(result)}="\$\{{nameof(result)}%"\$\{{nameof(result)}##*[![:space:]]}"}" $
    return result
}

pub fun lowercase(text: Text): Text {
    if shellname() == "bash" and shellversion() < [4, 3] {
        trust $ {nameof(text)}="\$(printf '%s' "{text}" | tr '[:upper:]' '[:lower:]')" $
    } else {
        trust $
            typeset -l {nameof(text)}
            {nameof(text)}="{text}"
        $
    }
    return text
}

pub fun uppercase(text: Text): Text {
    if shellname() == "bash" and shellversion() < [4, 3] {
        trust $ {nameof(text)}="\$(printf '%s' "{text}" | tr '[:lower:]' '[:upper:]')" $
    } else {
        trust $
            typeset -u {nameof(text)}
            {nameof(text)}="{text}"
        $
    }
    return text
}

pub fun parse_int(text: Text): Int? {
    $ [ -n "{text}" ] && [ "{text}" -eq "{text}" ] 2>/dev/null $?
    return text as Int
}

pub fun parse_num(text: Text): Num? {
    const re_int="^-?[0-9]+$"
    const re_float="^-?[0-9]*\.[0-9]+$"

    $ [[ {text} =~ {re_int} ]] || [[ {text} =~ {re_float} ]] $?
    return text as Num
}

pub fun split_chars(text: Text): [Text] {
    let chars = [Text]
    trust $ for ((i=0; i<\$\{#{nameof(text)}}; i++)); do
        {nameof(chars)}+=( "\$\{{nameof(text)}:\$i:1}" );
    done $
    return chars
}

pub fun text_contains(source: Text, search: Text): Bool {
    trust $ [[ "{source}" == *"{search}"* ]] $
    return status() == 0
}

pub fun text_contains_any(source: Text, searches: [Text]): Bool {
    for search in searches {
        if text_contains(source, search) {
            return true
        }
    }

    return false
}

pub fun text_contains_all(source: Text, searches: [Text]): Bool {
    for search in searches {
        if not text_contains(source, search) {
            return false
        }
    }
    return true
}

pub fun match_regex(source: Text, search: Text, extended: Bool = false): Bool {
    trust {
        const sed_version = sed_version()
        search = replace(search, "/", "\/")
        let output = ""
        if sed_version == SED_VERSION_GNU or sed_version == SED_VERSION_BUSYBOX {
            // '\b' is supported but not in POSIX standards. Disable it
            search = replace(search, "\\b", "\\\b")
        }
        if extended {
            // GNU sed versions 4.0 through 4.2 support extended regex syntax,
            // but only via the "-r" option
            if sed_version == SED_VERSION_GNU {
                // '\b' is not in POSIX standards. Disable it
                search = replace(search, "\b", "\\b")
                output = $ command sed -r -ne "/{search}/p" <<<"{source}" $
            } else {
                output = $ command sed -E -ne "/{search}/p" <<<"{source}" $
            }
        } else {
            if sed_version == SED_VERSION_GNU or sed_version == SED_VERSION_BUSYBOX {
                // GNU Sed BRE handle \| as a metacharacter, but it is not POSIX standands. Disable it
                search = replace(search, "\|", "|")
            }
            output = $ command sed -ne "/{search}/p" <<<"{source}" $
        }
        if output != "" {
            return true
        }
    }
    return false
}

pub fun match_regex_any(text: Text, terms: [Text]): Bool {
    for term in terms {
        if match_regex(text, term, false) {
            return true
        }
    }

    return false
}

pub fun reversed(text: Text): Text {
    return trust $ rev <<< "{text}" $
}

pub fun starts_with(text: Text, prefix: Text): Bool {
    trust $ [[ "{text}" == "{prefix}"* ]] $
    return status() == 0
}

pub fun ends_with(text: Text, suffix: Text): Bool {
    trust $ [[ "{text}" == *"{suffix}" ]] $
    return status() == 0
}

pub fun char_at(text: Text, index: Int): Text {
    let result = ""
    trust $ {nameof(result)}="\$\{{nameof(text)}:{index}:1}" $
    return result
}

pub fun capitalized(text: Text): Text {
    trust {
        if len(text) == 0 {
            return text
        }
        if sed_version() == SED_VERSION_GNU {
            // GNU sed supports \U
            return $ printf '%s\n' "{text}" | command sed 's/^\(.\)/\U\1/' $
        }
        const first_letter = uppercase(char_at(text, 0))
        return first_letter + slice(text, 1)
    }
}

pub fun lpad(text: Text, pad: Text, length: Int): Text {
    if length <= len(text): return text
    const pad_len = length - len(text)
    let padding = ""
    trust $ printf -v {nameof(padding)} "%{pad_len}s" "" $
    trust $ {nameof(padding)}="\$\{{nameof(padding)}// /{pad}}" $
    return padding + text
}

pub fun rpad(text: Text, pad: Text, length: Int): Text {
    if length <= len(text): return text
    const pad_len = length - len(text)
    let padding = ""
    trust $ printf -v {nameof(padding)} "%{pad_len}s" "" $
    trust $ {nameof(padding)}="\$\{{nameof(padding)}// /{pad}}" $
    return text + padding
}

pub fun cpad(text: Text, pad: Text, length: Int): Text {
    const text_length = len(text)
    if length <= text_length: return text

    const total_padding = length - text_length
    const left_padding_length = text_length + total_padding / 2
    const left_padded = lpad(text, pad, left_padding_length)
    const center_padded = rpad(left_padded, pad, length)

    return center_padded
}

pub fun zfill(text: Text, length: Int): Text {
    return lpad(text, "0", length)
}

pub fun count_lines(text: Text): Int {
    if text == "": return 0
    return trust $ wc -l <<< "{text}" | tr -d ' ' $ as Int
}

pub fun count_words(text: Text): Int {
    return trust $ wc -w <<< "{text}" | tr -d ' ' $ as Int
}

pub fun count_chars(text: Text): Int {
    return trust $ printf "%s" "{text}" | wc -m | tr -d ' ' $ as Int
}

pub fun sort_lines(text: Text, desc: Bool = false, numeric: Bool = false): Text {
    let args = ""
    if desc: args += "r"
    if numeric: args += "n"
    return trust $ sort -{args} <<< "{text}" $
}

pub fun uniq_lines(text: Text, remove_all: Bool = false): Text {
    if not remove_all:
        return trust $ uniq <<< "{text}" $
    else:
        return trust $ awk '!seen[\$0]++' <<< "{text}" $
}

pub fun text_find(text: Text, value: Text): Int {
    for index, element in split_chars(text) {
        if value == element {
            return index
        }
    }
    return -1
}

