pub fun list_deps() {
    const project = locate_project()
    if project[0] != "yes" {
        fatal("Cannot list deps outside of project.")
    }

    const project = project[1]
    const dependencies = get_project_properties(project, "dependencies")

    echo("{len(dependencies)} Dependencies:")
