pub fun get_os(): Text {
    // Determine OS type
    const os_type = trust $ uname -s $

    if {
        os_type == "Darwin": return "apple-darwin"
        os_type != "Linux": fatal("Unsupported OS type: {os_type}")
    }

    const is_musl = not has_failed("ls -l /lib | grep libc.musl")

    return is_musl
        then "linux-musl"
        else "linux-gnu"
}

pub fun get_arch(): Text {
    // Determine architecture
    const arch_type = trust $ uname -m $

    const arch = array_contains(["arm64", "aarch64"], arch_type)
        then "aarch64"
        else "x86_64"

    return arch
}

pub fun get_amethyst_data_dir(): Text {
    const home = trust env_var_get("HOME")
    const path = "{home}/.local/share/amethyst"

    $ mkdir -p "{path}" $ failed {
        fatal("Failed to create {path} directory.")
    }

    return realpath(path)
}

pub fun get_amethyst_bin_dir(): Text {
    const home = trust env_var_get("HOME")
    const path = "{home}/.local/bin/amethyst.bin"

    $ mkdir -p "{path}" $ failed {
        fatal("Failed to create {path} directory.")
    }

    return realpath(path)
}

import { match_regex, split_lines } from "std/text"

import { fatal } from "./utils.ab"

pub fun get_amber_tags(): [Text] {
    const json = $ curl -s -f "https://api.github.com/repos/amber-lang/amber/tags" $ failed {
        fatal("Failed to fetch tags from GitHub API.")
    }

    const tags = trust $ echo "{json}" | jq '.[] | .name' -r $
    const split = split_lines(tags)

    let filtered = [Text]

    for tag in split {
        // filter out early versions
        if {
            // match versions that do not start with `0.`
            match_regex(tag, "^[1-9]+", true): filtered += [tag]

            // match versions that start with `0.` but have a minor version equal to or greater than `4`
            match_regex(tag, "^0\\.[4-9]+", true): filtered += [tag]
        }
    }

    return filtered
}

