pub fun locate_project(): [Text] {
    let cwd = trust $ pwd $

    loop {
        if not dir_exists(cwd) {
            return ["no", ""]
        }

        if file_exists("{cwd}/amethyst.ini") {
            return ["yes", cwd]
        }

        if cwd == "/" {
            break
        }

        const new_cwd = parent_dir(cwd)
        cwd = new_cwd
    }

    return ["no", ""]
}

pub fun open_ini(ini_file: Text) {
    const tmp_dir = trust env_var_get("AM_INI_DIR")

    const lines_ = trust file_read(ini_file)
    let current_section = ""

    for line in split_lines(lines_) {
        const line = trim(line)
        if starts_with(line, "#") or line == "" {
            continue
        }

        const is_section = starts_with(line, "[") and ends_with(line, "]")
        if is_section {
            current_section = line
            for i in ["[", "]"] {
                current_section = replace(current_section, i, "")
            }

            trust dir_create("{tmp_dir}/{current_section}")
            continue
        }

        const segments = split(line, "=")
        if len(segments) != 2 {
            continue
        }

        const key = trim(segments[0])
        const value = trim(segments[1])

        trust file_write("{tmp_dir}/{current_section}/{key}", value)
    }
}

pub fun require_project(): Text {
    const result = locate_project()
    if result[0] == "no" {
        fatal("Failed to locate an 'amethyst.ini' file, make sure you are in a project's (sub)directory.")
    }

    if not env_var_test("AM_INI_DIR") {
        const tmp_dir = temp_dir_create("amethyst.XXXXXXXXXX", true, true) failed {
            fatal("Failed to create tmp dir")
        }
        env_var_set("AM_INI_DIR", tmp_dir) failed {
            fatal("Failed to set env var")
        }
        open_ini("{result[1]}/amethyst.ini")
    }

    return result[1]
}

pub fun close_ini(ini_file: Text) {
    const tmp_dir = trust env_var_get("AM_INI_DIR")
    let buffer = ""

    const sections = trust file_glob("{tmp_dir}/*")
    for section in sections {
        const section = basename(section)
        buffer += "[{section}]\n"

        const keys = trust file_glob("{tmp_dir}/{section}/*")
        for entry in keys {
            const key = basename(entry)
            const value = trust file_read(entry)
            buffer += "{key} = {value}\n"
        }

        buffer += "\n"
    }

    trust file_write(ini_file, trim(buffer))
}

pub fun list_ini_sections(): [Text] {
    const tmp_dir = trust env_var_get("AM_INI_DIR")
    const sections = trust file_glob("{tmp_dir}/*")

    let section_names = [Text]
    for section in sections {
        section_names += [basename(section)]
    }

    return section_names
}

pub fun list_ini_section_properties(section: Text): [Text] {
    const tmp_dir = trust env_var_get("AM_INI_DIR")
    const keys = trust file_glob("{tmp_dir}/{section}/*")

    let key_names = [Text]
    for key in keys {
        key_names += [basename(key)]
    }

    return key_names
}

pub fun list_ini_section_values(section: Text): [Text] {
    const tmp_dir = trust env_var_get("AM_INI_DIR")
    const keys = trust file_glob("{tmp_dir}/{section}/*")

    let values = [Text]
    for key in keys {
        values += [trust file_read(key)]
    }

    return values
}

pub fun get_ini_value(section: Text, property: Text): Text {
    const tmp_dir = trust env_var_get("AM_INI_DIR")

    const path = "{tmp_dir}/{section}/{property}"
    if not file_exists(path) {
        return ""
    }

    return trust file_read(path)
}

pub fun set_ini_value(section: Text, property: Text, value: Text) {
    const tmp_dir = trust env_var_get("AM_INI_DIR")

    if not dir_exists("{tmp_dir}/{section}"):
        trust dir_create("{tmp_dir}/{section}")

    const path = "{tmp_dir}/{section}/{property}"
    trust file_write(path, value)
}

pub fun delete_ini_property(section: Text, property: Text) {
    const tmp_dir = trust env_var_get("AM_INI_DIR")
    trust rm("{tmp_dir}/{section}/{property}")
}

pub fun get_project_properties(project: Text, section: Text): [Text] {
    const project_file = "{project}/amethyst.ini"
    if not file_exists(project_file) {
        return [Text]
    }

    let properties = [Text]

    const lines_ = trust file_read(project_file)
    let current_section = ""

    for line in split_lines(lines_) {
        const line = trim(line)

        if starts_with(line, "#") or line == "" {
            continue
        }

        const is_section = starts_with(line, "[") and ends_with(line, "]")
        if is_section {
            current_section = line
            for i in ["[", "]"] {
                current_section = replace(current_section, i, "")
            }
            continue
        }

        const segments = split(line, "=")
        if len(segments) != 2 {
            continue
        }

        const key = trim(segments[0])
        const value = trim(segments[1])

        if current_section == section {
            properties += [key]
        }
    }

    return properties
}

pub fun get_project_property(project: Text, section: Text, property: Text): Text {
    const project_file = "{project}/amethyst.ini"
    if not file_exists(project_file) {
        return ""
    }

    const lines_ = trust file_read(project_file)
    let current_section = ""

    for line in split_lines(lines_) {
        const line = trim(line)

        if starts_with(line, "#") or line == "" {
            continue
        }

        const is_section = starts_with(line, "[") and ends_with(line, "]")
        if is_section {
            current_section = line
            for i in ["[", "]"] {
                current_section = replace(current_section, i, "")
            }
            continue
        }

        const segments = split(line, "=")
        if len(segments) != 2 {
            continue
        }

        const key = trim(segments[0])
        const value = trim(segments[1])

        if current_section == section and key == property {
            return value
        }
    }

    return ""
}

pub fun get_project_amber() {
    const project = locate_project()
    const version = get_ini_value("amethyst", "amber-version")

    if not is_available_locally(version) {
        if is_system_amber_correct(version) {
            return "system"
        }

        warn("Amber {version} is not available locally.")
        info("Checking if it is available for download...")

        if not is_available_remotely(version) {
            fatal("Couldn't satisfy version requirement for amber {version}")
        }

        info("Amber {version} is available for download.")
        if not env_var_test("CI") {
            if not input_confirm("Proceed with download?") {
                exit(1)
            }
        }

        info("Downloading amber {version}...")
        download(version)
    }

    return version
}

import { styled, env_var_get } from "std/env"

const BOLD = 1
const FG_RED = 31
const FG_YELLOW = 33
const FG_WHITE = 37
const BG_BLACK = 40

pub fun info(message: Text): Null {
    const tag = styled("info", BOLD, FG_WHITE, BG_BLACK)
    const items = ["[{tag}]: %s\n", message]

    trust $ printf "{items}" $
}

pub fun warn(message: Text): Null {
    const tag = styled("warn", BOLD, FG_YELLOW, BG_BLACK)
    const items = ["[{tag}]: %s\n", message]

    trust $ printf "{items}" $
}

pub fun fatal(message: Text): Null {
    const tag = styled("fatal", BOLD, FG_RED, BG_BLACK)
    const items = ["[{tag}]: %s\n", message]

    trust $ printf "{items}" $
    exit 1
}

