import { env_var_get, env_var_test } from "std/env"
import { starts_with } from "std/text"

let tsl = trust $tput tsl$
let fsl = trust $tput fsl$
let smcup = trust $tput smcup$
let rmcup = trust $tput rmcup$

let TERM = trust env_var_get("TERM")

fun can_set_title(): Bool
{
    let has_statusline = true

    $tput hs$ failed {
        // For some reason, default xterm won't communicate statusline.
        // We need to set TERM=xterm+sl to get the info.
        if starts_with(TERM, "xterm") {
            trust $TERM=xterm+sl tput hs$
            if status == 0 {
                tsl = trust $TERM=xterm+sl tput tsl$
                fsl = trust $TERM=xterm+sl tput fsl$
            } else {
                has_statusline = false
            }
        } else {
            has_statusline = false
        }
    }

    return has_statusline
}

/// Set the title for the current window, if possible.
///
/// Does nothing otherwise.
pub fun set_title(title: Text = ""): Null
{
    if can_set_title():
        trust $>&2 echo {tsl + title + fsl}$
}

/// Create and enter an alt-buffer in the terminal.
pub fun enter_alt_buffer(): Null
{
    trust $>&2 echo {smcup}$
}

/// Close the alt-buffer in the terminal.
pub fun exit_alt_buffer(): Null
{
    trust $>&2 echo {rmcup}$
}

/// Shorthand to exit alt-buffer and clear terminal title.
pub fun teardown(failure: Bool = false): Null
{
    if failure {
        echo "Press any key to continue..."
        trust $read -n 1$
    }
    set_title()
    exit_alt_buffer()
}

import * from "std/text"
import * from "./mod.ab"
import * from "./help.ab"
import * from "../utils.ab"

fun read_stdin_options(): [Text] {
    let options = [Text]
    const is_tty = trust $ [ -t 0 ] && echo "true" || echo "false" $
    if is_tty == "false" {
        trust $ while IFS= read -r line || [[ -n "\$line" ]]; do {nameof(options)}+=("\$line"); done $
    }
    return options
}

pub fun execute_choose(parameters: [Text]): Text {
    let cursor = "> "
    let header = "\x1b[1m" + colored_primary("Choose: ")
    let options = read_stdin_options()
    let multi = false
    let limit = -1
    let page_size = 10 

    for param in parameters[2..len(parameters)] {
        if {
            param == "-h" or param == "--help" {
                print_choose_help()
                exit(0)
            }
            starts_with(param, "--cursor=") {
                cursor = slice(param, len("--cursor="))
            }
            starts_with(param, "--header=") {
                header = slice(param, len("--header="))
            }
            starts_with(param, "--limit=") {
                const value = slice(param, len("--limit="))
                limit = parse_int(value) failed {
                    eprintf_colored("ERROR: Invalid limit value: " + value + "\n", 31)
                    exit(1)
                }
                multi = true
            }
            param == "--no-limit" {
                multi = true
            }
            starts_with(param, "--page-size=") {
                const value = slice(param, len("--page-size="))
                page_size = parse_int(value) failed {
                    eprintf_colored("ERROR: Invalid page-size value: " + value + "\n", 31)
                    exit(1)
                }
            }
            else {
                options += [param]
            }
        }
    }

    const display_header = header == "" or has_ansi_escape(header) then escape_ansi(header) else "\\x1b[1m" + colored_primary(header)

    if multi {
        const results = xyl_multi_choose(options, cursor, display_header, limit, page_size)
        return join(results, "\n")
    }

    return xyl_choose(options, cursor, display_header, page_size)
}

import * from "std/env"
import * from "../utils.ab"
import * from "./engine.ab"

/// Prompts the user to choose a single option from a list.
///
/// ### Parameters
/// - `options`: The list of options to choose from.
/// - `cursor`: The cursor text to indicate the selected option.
/// - `header`: An optional header message to display above the options. (ANSI supported)
/// - `page_size`: The number of options to display per page.
pub fun xyl_choose(
    options: [Text],
    cursor: Text = "> ",
    header: Text = "\x1b[1mChoose:\x1b[0m",
    page_size: Int = 10,
): Text {
    // `len` copies the whole array, so the count is taken once and reused.
    const total = len(options)
    if total == 0 {
        eprintf_colored("ERROR: No options provided.\n", 31)
        exit(1)
    }

    chooser_begin(total, page_size, header, cursor, false, -1)
    let need_page = true
    loop {
        if need_page {
            let page = [Text]
            const start = chooser_page_start()
            const count = chooser_page_count()
            for i in start..start + count {
                page += [options[i]]
            }
            chooser_set_page(page)
        }
        const step = chooser_step()
        if step == CHOOSER_DONE {
            break
        }
        need_page = step == CHOOSER_NEED_PAGE
    }

    const selected = chooser_selected()
    chooser_end()
    return options[selected]
}

/// Prompts the user to choose multiple options from a list.
///
/// ### Parameters
/// - `options`: The list of options to choose from.
/// - `cursor`: The cursor text to indicate the selected option.
/// - `header`: An optional header message to display above the options. (ANSI supported)
/// - `limit`: The maximum number of options the user can select. Use -1 for no limit.
/// - `page_size`: The number of options to display per page.
pub fun xyl_multi_choose(
    options: [Text],
    cursor: Text = "> ",
    header: Text = "Choose:",
    limit: Int = -1,
    page_size: Int = 10,
): [Text] {
    const total = len(options)
    if total == 0 {
        eprintf_colored("ERROR: No options provided.\n", 31)
        return [Text]
    }

    chooser_begin(total, page_size, header, cursor, true, limit)
    let need_page = true
    loop {
        if need_page {
            let page = [Text]
            const start = chooser_page_start()
            const count = chooser_page_count()
            for i in start..start + count {
                page += [options[i]]
            }
            chooser_set_page(page)
        }
        const step = chooser_step()
        if step == CHOOSER_DONE {
            break
        }
        need_page = step == CHOOSER_NEED_PAGE
    }

    chooser_end()

    let result = [Text]
    for i in 0..total {
        if chooser_is_checked(i) {
            result += [options[i]]
        }
    }
    return result
}

import * from "std/text"
import * from "std/env"

import * from "./mod.ab"
import * from "./help.ab"
import * from "../utils.ab"

pub fun execute_confirm(parameters: [Text]): Text {
    let header = "\x1b[1m" + colored_primary("Are you sure?")
    let default_yes = true

    for param in parameters {
        if {
            param == "-h" or param == "--help" {
                print_confirm_help()
                exit(0)
            }
            starts_with(param, "--header=") {
                header = slice(param, len("--header="))
            }
            starts_with(param, "--default=") {
                const value = slice(param, len("--default="))
                if {
                    value == "yes" or value == "y": default_yes = true
                    value == "no" or value == "n": default_yes = false
                    else: {
                        eprintf_colored("ERROR: Invalid default value: " + value + ". Use 'yes' or 'no'.\n", 31)
                        exit(1)
                    }
                }
            }
        }
    }

    const display_header = header == "" or has_ansi_escape(header) then escape_ansi(header) else "\\x1b[1m" + colored_primary(header)
    const result = xyl_confirm(display_header, default_yes)
    return result then "yes" else "no"
}

