    const small = term_width < 30
    const yes_label = cpad("Yes", " ", small then 5 else 11)
    const no_label = cpad("No", " ", small then 4 else 10)
    const gap = small then " " else "  "

    eprintf(" ")
    if selected {
        // Yes selected
        eprintf("\x1b[97m" + background_secondary(yes_label))
        eprintf(gap)
        // No not selected (dim)
        eprintf("\x1b[49;37m" + no_label + "\x1b[0m")
    } else {
        // No selected
        eprintf("\x1b[49;37m" + yes_label + "\x1b[0m")
        eprintf(gap)
        eprintf("\x1b[97m" + background_secondary(no_label))
    }
}

/// Prompts the user with a Yes/No confirmation dialog.
///
/// ### Parameters
/// - `header`: The header message to display above the options. (ANSI supported)
/// - `default_yes`: Whether Yes is selected by default. Default is true.
///
/// ### Returns
/// - `true` if the user selected Yes, `false` if No.
pub fun xyl_confirm(
    header: Text = "Are you sure?",
    default_yes: Bool = true,
): Bool {
    stty_lock()
    hide_cursor()

    const term_width = term_width()

    if header != "" {
        eprintf(cutoff_text(header, term_width) + "\n\n")
    }

    let selected = default_yes

    // Render initial options
    render_confirm_options(selected, term_width)

    eprintf("\n\n")
    // "←→ select • enter confirm • y yes • n no" = 9 + 3 + 13 + 3 + 5 + 3 + 4 = 40
    render_tooltip(["←→", "select", "enter", "confirm", "y", "yes", "n", "no"], 40, term_width)
    go_up(2)

    loop {
        const key = get_key()

        if {
            key == "LEFT" or key == "h" or key == "RIGHT" or key == "l" {
                if {
                    selected {
                        selected = false
                        eprintf("\x1b[G\x1b[K")
                        render_confirm_options(selected, term_width)
                    }
                    not selected {
                        selected = true
                        eprintf("\x1b[G\x1b[K")
                        render_confirm_options(selected, term_width)
                    }
                }
            }
            key == "y" or key == "Y" {
                selected = true
                break
            }
            key == "n" or key == "N" {
                selected = false
                break
            }
            key == "INPUT" or key == "SPACE" {
                break
            }
            else: continue
        }
    }

    // Clean up: remove options line and hint line
    let total_lines = 4
    if header != "" {
        total_lines += 1
    }

    go_down(2)
    remove_line(total_lines - 1)
    remove_current_line()

    stty_unlock()
    show_cursor()

    return selected
}

