pub fun execute_file(parameters: [Text]): Text {
    let cursor = "> "
    let start_path = ""
    let show_hidden = false
    let page_size = 10

    for param in parameters[2..len(parameters)] {
        if {
            param == "-h" or param == "--help" {
                print_file_help()
                exit(0)
            }
            starts_with(param, "--cursor=") {
                cursor = slice(param, len("--cursor="))
            }
            starts_with(param, "--path=") {
                start_path = slice(param, len("--path="))
            }
            param == "-a" or param == "--all" {
                show_hidden = true
            }
            starts_with(param, "--page-size=") {
                const value = slice(param, len("--page-size="))
                page_size = parse_int(value) failed {
                    eprintf_colored("ERROR: Invalid page-size value: " + value + "\n", 31)
                    exit(1)
                }
            }
            else {
                // Treat as start path if not a flag
                start_path = param
            }
        }
    }

    return xyl_file(start_path, cursor, show_hidden, page_size)
}

import * from "std/env"
import * from "std/text"
import * from "../utils.ab"
import * from "../choose/engine.ab"

/// Format a single entry for display
/// Directories are colored with accent color and have trailing /
fun format_entry_display(name: Text, file_type: Text, target: Text): Text {
    if file_type == "d" {
        return name + colored_primary("/")
    }
    if file_type == "l" {
        return name + colored_accent(" > ") + colored_primary(target)
    }
    return name
}

/// File browser that lets user navigate and select a file.
///
/// ### Parameters
/// - `start_path`: Starting directory path (default: current directory).
/// - `cursor`: The cursor text to indicate the selected option.
/// - `show_hidden`: Whether to show hidden files (starting with .).
/// - `page_size`: The number of entries to display per page.
pub fun xyl_file(
    start_path: Text = "",
    cursor: Text = "> ",
    show_hidden: Bool = false,
    page_size: Int = 10,
): Text {
    stty_lock()

    // Initialize current path
    let current_path = start_path
    if current_path == "" {
        current_path = get_cwd()
    }
    current_path = normalize_path(current_path)

    loop {
        eprintf(colored_primary("Loading files..."))

        const listed = get_directory_entries(current_path)

        // No display text is built here. The loop below formats one page at a
        // time, so a directory with thousands of entries only formats the
        // handful that are on screen.
        let names = [Text]
        let types = [Text]
        let targets = [Text]

        // Add parent directory entry (..)
        if current_path != "/" {
            names += [".."]
            types += ["d"]
            targets += [""]
        }

        const listed_count = len(listed) / ENTRY_STRIDE
        for i in 0..listed_count {
            const at = i * ENTRY_STRIDE
            const name = listed[at]
            // Skip hidden files if not showing them
            if not show_hidden and starts_with(name, ".") {
                continue
            }
            names += [name]
            types += [listed[at + 1]]
            targets += [listed[at + 2]]
        }

        const total = len(names)
        if total == 0 {
            eprintf_colored("ERROR: Directory is empty or inaccessible.\n", 31)
            stty_unlock()
            return ""
        }

        const header = colored_primary(current_path)
        remove_current_line()

        chooser_begin(total, page_size, header, cursor, false, -1)
        let need_page = true
        loop {
            if need_page {
                let page = [Text]
                const start = chooser_page_start()
                const count = chooser_page_count()
                for i in start..start + count {
                    page += [format_entry_display(names[i], types[i], targets[i])]
                }
                chooser_set_page(page)
            }
            const step = chooser_step()
            if step == CHOOSER_DONE {
                break
            }
            need_page = step == CHOOSER_NEED_PAGE
        }
        const selected_idx = chooser_selected()
        chooser_end()

        const name = names[selected_idx]
        const file_type = types[selected_idx]

        if {
            name == ".." {
                current_path = get_parent_dir(current_path)
            }
            file_type == "d" {
                current_path = path_join(current_path, name)
                current_path = normalize_path(current_path)
            }
            file_type == "l" {
                // Resolve symlink target path
                const target = targets[selected_idx]
                let target_path = target
                if not starts_with(target, "/") {
                    target_path = path_join(current_path, target)
                }
                // Follow symlink if it points to a directory, otherwise return path
                if dir_exists(target_path) {
                    current_path = target_path
                    current_path = normalize_path(current_path)
                } else {
                    stty_unlock()
                    return path_join(current_path, name)
                }
            }
            else: {
                stty_unlock()
                return path_join(current_path, name)
            }
        }
    }

    stty_unlock()
    return ""
}

import * from "std/text"
import * from "./mod.ab"
import * from "./help.ab"
import * from "../utils.ab"

fun read_stdin_options(): [Text] {
    let options = [Text]
    const is_tty = trust $ [ -t 0 ] && echo "true" || echo "false" $
    if is_tty == "false" {
        trust $ while IFS= read -r line || [[ -n "\$line" ]]; do {nameof(options)}+=("\$line"); done $
    }
    return options
}

pub fun execute_filter(parameters: [Text]): Text {
    let cursor = "> "
    let prompt = "/ "
    let placeholder = "Filter..."
    let header = ""
    let options = read_stdin_options()
    let multi = false
    let limit = -1
    let height = 10

    for param in parameters[2..len(parameters)] {
        if {
            param == "-h" or param == "--help" {
                print_filter_help()
                exit(0)
            }
            starts_with(param, "--cursor=") {
                cursor = slice(param, len("--cursor="))
            }
            starts_with(param, "--prompt=") {
                prompt = slice(param, len("--prompt="))
            }
            starts_with(param, "--placeholder=") {
                placeholder = slice(param, len("--placeholder="))
            }
            starts_with(param, "--header=") {
                header = slice(param, len("--header="))
            }
            starts_with(param, "--limit=") {
                const value = slice(param, len("--limit="))
                limit = parse_int(value) failed {
                    eprintf_colored("ERROR: Invalid limit value: " + value + "\n", 31)
                    exit(1)
                }
                multi = true
            }
            param == "--no-limit" {
                multi = true
            }
            starts_with(param, "--height=") {
                const value = slice(param, len("--height="))
                height = parse_int(value) failed {
                    eprintf_colored("ERROR: Invalid height value: " + value + "\n", 31)
                    exit(1)
                }
            }
            else {
                options += [param]
            }
        }
    }

    const display_header = header == "" or has_ansi_escape(header) then escape_ansi(header) else "\\x1b[1m" + colored_primary(header)
    const results = xyl_filter(options, prompt, placeholder, display_header, cursor, multi, limit, height)
    return join(results, "\n")
}

